//! S-D1 oracle: the Rust JSON codecs for `discs`, `folder_ids`, and
//! `image_files` must produce and accept the exact shapes the Go
//! repositories store.
//!
//! `tests/testdata/go_sql_json/data/go_sql_json.json` is generated by the
//! Go harness in `tests/testdata/go_sql_json/` (see its README for the
//! regeneration command). The harness drives the **real** `encoding/json`
//! over `map[int]string` and `[]string` — integer-key string order, the
//! nil vs empty spellings, the escaping, and the malformed read cases — so
//! the golden is Go production behaviour, not a re-statement.
//!
//! Unlike the S-A participant golden, this golden is **byte-stable**: the
//! harness never iterates a Go map for output order (key order is recorded
//! by a streaming decode that preserves input order). The tests compare
//! valid shapes structurally and, for discs, assert the **object key order
//! positionally** — Go's string-key sorting is the contract.

use std::collections::BTreeMap;
use std::path::Path;

use nd_db::sql_json::{
    marshal_discs, marshal_image_files, marshal_nullable_strings, unmarshal_discs,
    unmarshal_image_files, unmarshal_nullable_strings,
};
use serde::Deserialize;

/// True when any discs value carries a character Go's json.Marshal escapes
/// (<, >, &, U+2028, U+2029) — the settled divergence means those cases are
/// compared by round-trip, not by output bytes.
fn discs_need_parsed_comparison(discs: &DiscsIn) -> bool {
    discs.raw.values().any(|v| {
        v.as_str().is_some_and(|s| {
            s.contains('<')
                || s.contains('>')
                || s.contains('&')
                || s.contains('\u{2028}')
                || s.contains('\u{2029}')
        })
    })
}

/// True when any list element carries a character Go's json.Marshal escapes.
fn list_need_parsed_comparison(list: &ListIn) -> bool {
    list.raw.iter().any(|v| {
        v.as_str().is_some_and(|s| {
            s.contains('<')
                || s.contains('>')
                || s.contains('&')
                || s.contains('\u{2028}')
                || s.contains('\u{2029}')
        })
    })
}

fn golden_path() -> std::path::PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("tests/testdata/go_sql_json/data/go_sql_json.json")
}

/// The golden records `raw: null` (not an absent field) for nil inputs,
/// so `#[serde(default)]` alone does not catch it — treat JSON `null` as an
/// empty collection.
fn opt_map<'de, D: serde::Deserializer<'de>>(
    d: D,
) -> Result<serde_json::Map<String, serde_json::Value>, D::Error> {
    Ok(Option::deserialize(d)?.unwrap_or_default())
}

fn opt_list<'de, D: serde::Deserializer<'de>>(d: D) -> Result<Vec<serde_json::Value>, D::Error> {
    Ok(Option::deserialize(d)?.unwrap_or_default())
}

#[derive(Debug, Deserialize)]
struct DiscsIn {
    #[serde(default)]
    nil: bool,
    #[serde(default, deserialize_with = "opt_map")]
    raw: serde_json::Map<String, serde_json::Value>,
}

#[derive(Debug, Deserialize)]
struct ListIn {
    #[serde(default)]
    nil: bool,
    #[serde(default, deserialize_with = "opt_list")]
    raw: Vec<serde_json::Value>,
}
#[derive(Debug, Deserialize)]
struct ReadCase {
    #[serde(default)]
    json: String,
    kind: String,
    #[serde(default)]
    nil: bool,
}

#[derive(Debug, Deserialize)]
struct ReadResult {
    ok: bool,
    #[serde(default)]
    error: String,
    #[serde(default)]
    raw: String,
    #[serde(default)]
    is_array: bool,
    #[serde(default)]
    items: Vec<serde_json::Value>,
}

#[derive(Debug, Deserialize)]
struct Row {
    name: String,
    #[serde(default)]
    discs_in: Option<DiscsIn>,
    #[serde(default)]
    discs_out: Option<String>,
    #[serde(default)]
    string_list_in: Option<ListIn>,
    #[serde(default)]
    string_list_out: Option<String>,
    #[serde(default)]
    image_files_in: Option<ListIn>,
    #[serde(default)]
    image_files_out: Option<String>,
    #[serde(default)]
    read_case: Option<ReadCase>,
    #[serde(default)]
    read: Option<ReadResult>,
}

fn golden() -> Vec<Row> {
    let bytes = std::fs::read(golden_path())
        .unwrap_or_else(|e| panic!("read {}: {e}", golden_path().display()));
    serde_json::from_slice(&bytes).expect("parse go_sql_json golden")
}

fn by_name<'a>(rows: &'a [Row], name: &str) -> &'a Row {
    rows.iter()
        .find(|r| r.name == name)
        .unwrap_or_else(|| panic!("golden missing case {name:?}"))
}

/// `Option<Vec<String>>` → `Option<&[String]>` for the marshal fns.
fn list_arg(v: &Option<Vec<String>>) -> Option<&[String]> {
    v.as_deref()
}

/// `Option<BTreeMap<i64,String>>` → `Option<&BTreeMap<i64,String>>` for
/// `marshal_discs`.
fn discs_arg(v: &Option<BTreeMap<i64, String>>) -> Option<&BTreeMap<i64, String>> {
    v.as_ref()
}

// ---------------------------------------------------------------- discs ---

#[test]
fn discs_write_matches_go_oracle() {
    let rows = golden();
    for row in &rows {
        let Some(in_) = &row.discs_in else { continue };
        let Some(expected) = &row.discs_out else {
            continue;
        };
        let rust: Option<BTreeMap<i64, String>> = if in_.nil {
            None
        } else {
            let map: BTreeMap<i64, String> = in_
                .raw
                .iter()
                .map(|(k, v)| {
                    (
                        k.parse::<i64>().expect("discs golden key is integer"),
                        v.as_str()
                            .expect("discs golden value is a string")
                            .to_string(),
                    )
                })
                .collect();
            Some(map)
        };
        let got = marshal_discs(discs_arg(&rust));
        if discs_need_parsed_comparison(in_) {
            // Go escapes < > & U+2028 U+2029; serde_json does not (settled
            // divergence). Compare parsed structure + key order instead of
            // bytes.
            let go: serde_json::Value = serde_json::from_str(expected).unwrap();
            let rust: serde_json::Value = serde_json::from_str(&got).unwrap();
            assert_eq!(go, rust, "case {}: parsed discs differ from Go", row.name);
        } else {
            assert_eq!(
                &got, expected,
                "case {}: Rust marshal differs from Go",
                row.name
            );
        }
    }
}

#[test]
fn discs_write_nil_vs_empty_and_string_key_order() {
    // Go nil map -> `null`, non-nil empty map -> `{}` (pinned by the oracle
    // `discs_nil` / `discs_empty_non_nil` and asserted directly here).
    assert_eq!(marshal_discs(None), "null");
    let empty: BTreeMap<i64, String> = BTreeMap::new();
    assert_eq!(marshal_discs(Some(&empty)), "{}");
}

#[test]
fn discs_write_stringifies_keys_before_sorting() {
    // The core contract: numeric order would give 1, 2, 10, 100; Go's
    // string-key sort gives 1, 10, 100, 2. Insert in a scrambled order to
    // prove the codec sorts (not the caller).
    let mut discs: BTreeMap<i64, String> = BTreeMap::new();
    discs.insert(2, "Second".into());
    discs.insert(1, "One".into());
    discs.insert(10, "Ten".into());
    discs.insert(100, "Hundred".into());
    // Assert key order positionally (parsed, to survive escaping).
    let value: serde_json::Value = serde_json::from_str(&marshal_discs(Some(&discs))).unwrap();
    let keys: Vec<String> = value.as_object().unwrap().keys().cloned().collect();
    assert_eq!(
        keys,
        vec!["1", "10", "100", "2"],
        "discs keys must sort as strings (1, 10, 100, 2), not numerically"
    );
}

#[test]
fn discs_round_trips_every_golden_write_shape() {
    let rows = golden();
    for row in &rows {
        let Some(in_) = &row.discs_in else { continue };
        let Some(expected) = &row.discs_out else {
            continue;
        };
        let rust: Option<BTreeMap<i64, String>> = if in_.nil {
            None
        } else {
            Some(
                in_.raw
                    .iter()
                    .map(|(k, v)| (k.parse::<i64>().unwrap(), v.as_str().unwrap().to_string()))
                    .collect(),
            )
        };
        let json = marshal_discs(discs_arg(&rust));
        let back = unmarshal_discs(&json).unwrap();
        assert_eq!(back, rust, "case {}: discs round-trip", row.name);
        // Re-marshalling is stable.
        assert_eq!(marshal_discs(back.as_ref()), json);
        // And the re-marshalled bytes agree with the Go golden (parsed,
        // for the escape-divergence cases).
        if discs_need_parsed_comparison(in_) {
            let go: serde_json::Value = serde_json::from_str(expected).unwrap();
            let rust: serde_json::Value = serde_json::from_str(&json).unwrap();
            assert_eq!(go, rust, "case {}: re-marshal parsed vs Go", row.name);
        } else {
            assert_eq!(&json, expected, "case {}: re-marshal vs Go", row.name);
        }
    }
}

#[test]
fn discs_read_matches_go_oracle_valid_and_invalid() {
    let rows = golden();
    for row in &rows {
        let Some(rc) = &row.read_case else { continue };
        if rc.kind != "discs" {
            continue;
        }
        let Some(exp) = &row.read else { continue };
        let input = if rc.nil {
            "null".to_string()
        } else {
            rc.json.clone()
        };
        let got = unmarshal_discs(&input);
        if exp.ok {
            if exp.raw == "null" {
                // Go's nil map re-marshals to `null`; the Rust codec
                // decodes it to `Ok(None)` (not an error).
                assert!(
                    matches!(got, Ok(None)),
                    "case {}: Go read `null` -> nil map -> Ok(None), got {:?}",
                    row.name,
                    got.as_ref().err().map(|e| e.to_string())
                );
                continue;
            }
            let value: BTreeMap<i64, String> = serde_json::from_str(&exp.raw).unwrap_or_default();
            assert_eq!(
                got.ok(),
                Some(Some(value.clone())),
                "case {}: valid discs read (Go result {:?})",
                row.name,
                exp.raw
            );
            // Pin the exact string-key order recorded by Go's re-marshal, not
            // a re-derived expectation from the input keys. This also covers
            // alternate spellings such as `"1"` and `"01"`, which both parse
            // to int key 1 and keep the later value.
            assert_eq!(
                marshal_discs(Some(&value)),
                exp.raw,
                "case {}: Go re-marshal bytes and key order",
                row.name
            );
        } else {
            assert!(
                got.is_err(),
                "case {}: Go errors ({}) but Rust accepted",
                row.name,
                exp.error
            );
        }
    }
}

#[test]
fn discs_read_preserves_nil_vs_empty() {
    // `null` -> None (Go nil map); `{}` -> Some(empty).
    assert_eq!(unmarshal_discs("null").unwrap(), None);
    assert_eq!(unmarshal_discs("{}").unwrap(), Some(BTreeMap::new()));
}

#[test]
fn discs_read_malformed_errors_without_panicking() {
    // Non-integer key, non-string value, wrong top-level type, empty
    // string — each must be a structured error, never a panic.
    for bad in [
        r#"{"x":"a"}"#,
        r#"{"1":"a","2x":"b"}"#,
        r#"{"1":1}"#,
        r#"[1]"#,
        "",
    ] {
        let res = std::panic::catch_unwind(|| unmarshal_discs(bad));
        assert!(res.is_ok(), "unmarshal_discs({bad:?}) must not panic");
        let err = res.unwrap();
        assert!(err.is_err(), "unmarshal_discs({bad:?}) must error");
        // The error carries the column context for S-D3.
        assert!(
            err.unwrap_err().to_string().starts_with("discs:"),
            "error must name the discs column"
        );
    }
    // A JSON `null` value is NOT malformed — Go stores the zero value
    // `""` (no error; oracle case `read_discs_null_value`). Pinned
    // directly here.
    let mut one = std::collections::BTreeMap::new();
    one.insert(1, String::new());
    assert_eq!(unmarshal_discs(r#"{"1":null}"#).unwrap(), Some(one));
}

// ---------------------------------------------------------- folder_ids ---

#[test]
fn folder_ids_write_matches_go_oracle() {
    let rows = golden();
    for row in &rows {
        let Some(in_) = &row.string_list_in else {
            continue;
        };
        let Some(expected) = &row.string_list_out else {
            continue;
        };
        let rust: Option<Vec<String>> = if in_.nil {
            None
        } else {
            Some(
                in_.raw
                    .iter()
                    .map(|v| {
                        v.as_str()
                            .expect("list golden value is a string")
                            .to_string()
                    })
                    .collect(),
            )
        };
        let got = marshal_nullable_strings(list_arg(&rust));
        if list_need_parsed_comparison(in_) {
            // Settled escaping divergence — compare parsed structure.
            let go: serde_json::Value = serde_json::from_str(expected).unwrap();
            let rust: serde_json::Value = serde_json::from_str(&got).unwrap();
            assert_eq!(
                go, rust,
                "case {}: parsed folder_ids differ from Go",
                row.name
            );
        } else {
            assert_eq!(
                &got, expected,
                "case {}: Rust marshal differs from Go",
                row.name
            );
        }
    }
}

#[test]
fn folder_ids_write_nil_vs_empty() {
    // Go nil slice -> `null`, non-nil empty slice -> `[]`.
    assert_eq!(marshal_nullable_strings(None), "null");
    assert_eq!(marshal_nullable_strings(Some(&[])), "[]");
}

#[test]
fn folder_ids_round_trips_every_golden_write_shape() {
    let rows = golden();
    for row in &rows {
        let Some(in_) = &row.string_list_in else {
            continue;
        };
        let Some(expected) = &row.string_list_out else {
            continue;
        };
        let rust: Option<Vec<String>> = if in_.nil {
            None
        } else {
            Some(
                in_.raw
                    .iter()
                    .map(|v| v.as_str().unwrap().to_string())
                    .collect(),
            )
        };
        let json = marshal_nullable_strings(list_arg(&rust));
        let back = unmarshal_nullable_strings(&json).unwrap();
        assert_eq!(back, rust, "case {}: folder_ids round-trip", row.name);
        assert_eq!(marshal_nullable_strings(list_arg(&back)), json);
        if list_need_parsed_comparison(in_) {
            let go: serde_json::Value = serde_json::from_str(expected).unwrap();
            let rust: serde_json::Value = serde_json::from_str(&json).unwrap();
            assert_eq!(go, rust, "case {}: re-marshal parsed vs Go", row.name);
        } else {
            assert_eq!(&json, expected, "case {}: re-marshal vs Go", row.name);
        }
    }
}

#[test]
fn folder_ids_read_matches_go_oracle_valid_and_invalid() {
    let rows = golden();
    for row in &rows {
        let Some(rc) = &row.read_case else { continue };
        if rc.kind != "list" {
            continue;
        }
        let Some(exp) = &row.read else { continue };
        let input = if rc.nil {
            "null".to_string()
        } else {
            rc.json.clone()
        };
        let got = unmarshal_nullable_strings(&input);
        if exp.ok {
            let expected: Option<Vec<String>> = if exp.is_array {
                Some(
                    exp.items
                        .iter()
                        // Go converts a JSON `null` element to the zero
                        // value "" (the golden's `raw` re-marshal records
                        // that); mirror it.
                        .map(|v| match v.as_str() {
                            Some(s) => s.to_string(),
                            None => {
                                assert!(
                                    v.is_null(),
                                    "golden list element must be a string or null, got {v:?}"
                                );
                                String::new()
                            }
                        })
                        .collect(),
                )
            } else {
                // `null` into []string: no error, slice left nil.
                None
            };
            assert_eq!(
                got.ok(),
                Some(expected),
                "case {}: valid folder_ids read",
                row.name
            );
        } else {
            assert!(
                got.is_err(),
                "case {}: Go errors ({}) but Rust accepted",
                row.name,
                exp.error
            );
        }
    }
}

#[test]
fn folder_ids_read_preserves_nil_vs_empty() {
    // `null` -> None (Go nil slice); `[]` -> Some(empty).
    assert_eq!(unmarshal_nullable_strings("null").unwrap(), None);
    assert_eq!(unmarshal_nullable_strings("[]").unwrap(), Some(Vec::new()));
}

#[test]
fn folder_ids_read_malformed_errors_without_panicking() {
    for bad in [r#"["/a",1]"#, r#"{"1":"a"}"#, "", "12"] {
        let res = std::panic::catch_unwind(|| unmarshal_nullable_strings(bad));
        assert!(
            res.is_ok(),
            "unmarshal_nullable_strings({bad:?}) must not panic"
        );
        let err = res.unwrap();
        assert!(
            err.is_err(),
            "unmarshal_nullable_strings({bad:?}) must error"
        );
        assert!(
            err.unwrap_err().to_string().starts_with("folder_ids:"),
            "error must name the folder_ids column"
        );
    }
}

// ---------------------------------------------------------- image_files ---

#[test]
fn image_files_write_matches_go_oracle_special_nil() {
    let rows = golden();
    for row in &rows {
        let Some(in_) = &row.image_files_in else {
            continue;
        };
        let Some(expected) = &row.image_files_out else {
            continue;
        };
        let rust: Option<Vec<String>> = if in_.nil {
            None
        } else {
            Some(
                in_.raw
                    .iter()
                    .map(|v| v.as_str().unwrap().to_string())
                    .collect(),
            )
        };
        let got = marshal_image_files(list_arg(&rust));
        if list_need_parsed_comparison(in_) {
            let go: serde_json::Value = serde_json::from_str(expected).unwrap();
            let rust: serde_json::Value = serde_json::from_str(&got).unwrap();
            assert_eq!(
                go, rust,
                "case {}: parsed image_files differ from Go",
                row.name
            );
        } else {
            assert_eq!(
                &got, expected,
                "case {}: image_files marshal differs from Go",
                row.name
            );
        }
    }
    // The special case pinned directly: nil -> `[]` (NOT `null`), empty
    // non-nil -> `[]`. Both arms agree on empty.
    assert_eq!(marshal_image_files(None), "[]");
    assert_eq!(marshal_image_files(Some(&[])), "[]");
}

#[test]
fn image_files_round_trips_non_nil_write_shapes() {
    // The write side collapses nil to `[]`, so a full round-trip only
    // reconstructs non-nil inputs. nil -> `[]` -> Some([]) is the expected
    // asymmetry (asserted in the next test).
    let rows = golden();
    for row in &rows {
        let Some(in_) = &row.image_files_in else {
            continue;
        };
        if in_.nil {
            continue;
        }
        let rust: Option<Vec<String>> = Some(
            in_.raw
                .iter()
                .map(|v| v.as_str().unwrap().to_string())
                .collect(),
        );
        let json = marshal_image_files(list_arg(&rust));
        let back = unmarshal_image_files(&json).unwrap();
        assert_eq!(back, rust, "case {}: image_files round-trip", row.name);
        assert_eq!(marshal_image_files(list_arg(&back)), json);
    }
}

#[test]
fn image_files_read_null_is_none_empty_array_is_some_empty() {
    // Go's json.Unmarshal of `null` into []string leaves the slice nil;
    // `[]` yields an empty non-nil slice.
    assert_eq!(unmarshal_image_files("null").unwrap(), None);
    assert_eq!(unmarshal_image_files("[]").unwrap(), Some(Vec::new()));
}

#[test]
fn image_files_read_matches_go_oracle_valid_and_invalid() {
    // image_files shares the list read semantics with folder_ids; the
    // oracle's `read` kind "list" cases pin the Go behaviour. The codec
    // under test is unmarshal_image_files, which must agree.
    let rows = golden();
    for row in &rows {
        let Some(rc) = &row.read_case else { continue };
        if rc.kind != "list" {
            continue;
        }
        let Some(exp) = &row.read else { continue };
        let input = if rc.nil {
            "null".to_string()
        } else {
            rc.json.clone()
        };
        let got = unmarshal_image_files(&input);
        if exp.ok {
            let expected: Option<Vec<String>> = if exp.is_array {
                Some(
                    exp.items
                        .iter()
                        // Go converts a JSON `null` element to the zero
                        // value "" (the golden's `raw` re-marshal records
                        // that); mirror it.
                        .map(|v| match v.as_str() {
                            Some(s) => s.to_string(),
                            None => {
                                assert!(
                                    v.is_null(),
                                    "golden list element must be a string or null, got {v:?}"
                                );
                                String::new()
                            }
                        })
                        .collect(),
                )
            } else {
                None
            };
            assert_eq!(
                got.ok(),
                Some(expected),
                "case {}: image_files read agrees with Go list read",
                row.name
            );
        } else {
            assert!(
                got.is_err(),
                "case {}: image_files read must error like Go",
                row.name
            );
        }
    }
}

#[test]
fn image_files_read_malformed_errors_without_panicking() {
    for bad in [r#"["/a",1]"#, r#"{"1":"a"}"#, ""] {
        let res = std::panic::catch_unwind(|| unmarshal_image_files(bad));
        assert!(res.is_ok(), "unmarshal_image_files({bad:?}) must not panic");
        let err = res.unwrap();
        assert!(err.is_err(), "unmarshal_image_files({bad:?}) must error");
        assert!(
            err.unwrap_err().to_string().starts_with("image_files:"),
            "error must name the image_files column"
        );
    }
}

// --------------------------------------------- escape/round-trip fidelity ---

#[test]
fn unicode_and_special_chars_round_trip() {
    // The oracle's escaping cases (< > & U+2028 U+2029, é ü) pin Go's
    // escaped bytes; Rust's serde does not escape them, but round-trip
    // fidelity is the contract — decode must recover the exact characters.
    let rows = golden();
    let esc = by_name(&rows, "discs_escaping_unicode");
    let in_ = esc.discs_in.as_ref().unwrap();
    let discs: BTreeMap<i64, String> = in_
        .raw
        .iter()
        .map(|(k, v)| (k.parse().unwrap(), v.as_str().unwrap().to_string()))
        .collect();
    let json = marshal_discs(Some(&discs));
    let back: BTreeMap<i64, String> = serde_json::from_str(&json).unwrap();
    assert_eq!(back, discs, "discs escaping round-trip");

    let list = by_name(&rows, "folder_ids_escaping");
    let lin = list.string_list_in.as_ref().unwrap();
    let strings: Vec<String> = lin
        .raw
        .iter()
        .map(|v| v.as_str().unwrap().to_string())
        .collect();
    let ljson = marshal_nullable_strings(Some(&strings));
    let lback: Vec<String> = serde_json::from_str(&ljson).unwrap();
    assert_eq!(lback, strings, "folder_ids escaping round-trip");
}
